"use strict";
window.SourceRepository={create(storage,source,M,entry){
 const key='campaign-atlas:source-operation:'+entry.campaignId+':'+source.id+':',spatial={nodes:{HQ:{name:entry.campaign+' HQ',echelon:'Operation',x:160,y:150},M04:{name:entry.title+' mission HQ',echelon:'Formation',x:700,y:220},depot:{name:'Forward supply depot',x:200,y:340}},routes:{M04:[[200,340],[380,300],[510,210],[700,285]]}};let current=null;
 const read=id=>CampaignWorld.validate(JSON.parse(storage.getItem(key+id)),M);
 function save(w){if(current&&read(current.id).revision!==current.revision)throw Error('Operation changed in another tab. Reload.');const next=CampaignWorld.validate(w,M);next.revision++;storage.setItem(key+next.id,JSON.stringify(next));storage.setItem(key+'active',next.id);return current=next;}
 return {preview:()=>CampaignWorld.create(M.initial("preview"),"0".repeat(32),spatial),get:()=>current,load(){const id=storage.getItem(key+'active');return current=id?read(id):null;},save,start(staff){const op=M.initial(crypto.randomUUID(),'operational',staff),seed=Array.from(crypto.getRandomValues(new Uint8Array(16))).map(n=>n.toString(16).padStart(2,'0')).join(''),w=CampaignWorld.create(op,seed,spatial);w.title=entry.campaign;w.campaignId=entry.campaignId;w.operationDate=entry.date;w.atlasOrigin=[entry.anchor.x,entry.anchor.y];return save(w);},execute(c){if(!current)throw Error('Start operation');let w={...current,operation:M.execute(current.operation,c)};if(c.type==='commit'){w=CampaignWorld.bindMission(w,'M04',source,M);w.missions.M04.adaptation='Source boards retain original local coordinates and setup restrictions. Operational map is illustrative.';}return save(w);}};
}};
